Ext.define('ViewDashlet.view.Utils', {
    extend: 'Ext.Base',

    requires: [
        'DashletHTML.controller.Translator'
    ],

    processErrorMessage: function(response) {


        var me = this,
            m, d;

        if (response.timeout || response.status == 408 ) {
            m = DashletHTML.controller.Translator.getMessage("timeoutMessage");
        } else {

            if (response.status == 401) {
                m = DashletHTML.controller.Translator.getMessage("sessionExpired");
                d = me.getErrorDetail(response);
            }
            else if ( response.status == 400  ){
                m = DashletHTML.controller.Translator.getMessage("badRequest");
                d = me.getErrorDetail(response);

            }else if ( response.status == 500 ){
                m = DashletHTML.controller.Translator.getMessage("internaError");
                d = me.getErrorDetail(response);
            }
            else {
                if (typeof response.responseText === 'string') {
                    try{
                        message = JSON.parse(response.responseText);
                        m = message.Fault.Message;
                        d = message.Fault.Detail;
                    }catch(ex){
                        m = DashletHTML.controller.Translator.getMessage("unexpectedError");
                        d = ex.toString();
                    }
                } else if (response.internalErrorMessage !== undefined) {
                    m = response.internalErrorMessage.message;
                    d = response.internalErrorMessage.detail;
                } else {
                    message = response.responseText;
                    m = message.Fault.Message;
                    d = message.Fault.Detail;
                }
            }
        }

        return {
            message: m,
            detail: d
        };
    },

    getErrorDetail: function(response) {
        var d = null;
        try{
            var parser = JSON.parse(response.responseText);
            d = parser.Fault.Detail;
        }catch(e){

        }

        return d;

    },

    buildDrillQuery: function(dimension, uname, encode) {
        var me = this,
            query = "",
            newDimension = me.escapeXML(dimension),
            newUName = me.escapeXML(uname);


        query += '    <DimensionQuery name="'+newDimension+'" xmlns="http://ns.ideasoft.biz/o3bi/schema/ViewQuery/2011-01"> 	    ';
        query += '        <joq:dimensionView xmlns:joq="http://ns.ideasoft.biz/o3bi/schema/JOlapQuery/2012-02">						';
        query += '            <joq:dimension>                                                                  						';
        query += '                <joq:name>'+newDimension+'</joq:name>                                  							';
        query += '            </joq:dimension>                                                                 						';
        query += '            <joq:drill>                                                                      						';
        query += '                <joq:setAction>INITIAL</joq:setAction>                                       						';
        query += '                <joq:drillType>CHILDREN</joq:drillType>                                      						';
        query += '                <joq:drillMember uniqueName="'+newUName+'"/>                                						';
        query += '            </joq:drill>                                                                     						';
        query += '        </joq:dimensionView>                                                                 						';
        query += '    </DimensionQuery>                                                                        						';


        return encode ?  Base64.encode(query) : query;
    },

    buildSingleMemberQuery: function(dimension, uname, encode) {
        var me = this,
            query = "",
            newDimension = me.escapeXML(dimension),
            newUName = me.escapeXML(uname);

        query += '<DimensionQuery name="'+newDimension+'">                                                  ';
        query += '    <joq:dimensionView xmlns:joq="http://ns.ideasoft.biz/o3bi/schema/JOlapQuery/2012-02"> ';
        query += '        <joq:dimension>                                                                   ';
        query += '            <joq:name>'+newDimension+'</joq:name>                                         ';
        query += '        </joq:dimension>                                                                  ';
        query += '        <joq:memberListFilter>                                                            ';
        query += '            <joq:setAction>INITIAL</joq:setAction>                                        ';
        query += '            <joq:member uniqueName="'+newUName+'"/>                                       ';
        query += '        </joq:memberListFilter>                                                           ';
        query += '    </joq:dimensionView>                                                                  ';
        query += '</DimensionQuery>																			';


        return encode ?  Base64.encode(query) : query;
    },

    escapeXML: function(str) {
        return str.replace(/[<>&'"]/g, function (c) {
            switch (c) {
                case '<': return '&lt;';
                case '>': return '&gt;';
                case '&': return '&amp;';
                case '\'': return '&apos;';
                case '"': return '&quot;';
            }
        });
    }

});